        // 6. 건물 폴리곤 레이어 시각화 및 데이터 매칭 엔진
        // [사용자 요청] 클릭 가능한 영역 제한 (좌측: 성수4길, 우측: 뚝섬로 13길, 상단: 연무장길, 하단: 뚝섬로)
        var CLICKABLE_BOUNDS = L.latLngBounds(
            [37.5390, 127.0490], // 남서쪽 (하단 좌측) 좌표
            [37.5446, 127.0585]  // 북동쪽 (상단 우측) 좌표
        );

        function isFeatureInBounds(feature) {
            if (!feature.geometry || !feature.geometry.coordinates || feature.geometry.coordinates.length === 0) return false;
            var coords = feature.geometry.coordinates[0][0]; // Polygon의 첫 번째 좌표
            if (!coords) return false;
            var latLng = L.latLng(coords[1], coords[0]);
            return CLICKABLE_BOUNDS.contains(latLng);
        }

        L.geoJSON(buildingGeoJSON, {
            style: function(feature) {
                var rawAddr = feature.properties.주소; 
                var addr = normalizeAddress(rawAddr);  // ★교정 완료: 맵에 그릴 때 주소 표준화 매칭
                var hasData = buildingGroup[addr] && buildingGroup[addr].length > 0;
                
                // 클릭 가능한 영역 내인지 확인
                var inBounds = isFeatureInBounds(feature);
                
                return {
                    color: inBounds ? "#1b365d" : "#e2e8f0",       
                    weight: inBounds ? 1.5 : 1,
                    fillColor: inBounds ? (hasData ? "#2B6CB0" : "#CBD5E0") : "#f8fafc", 
                    fillOpacity: inBounds ? 0.6 : 0.2
                };
            },
            onEachFeature: function(feature, layer) {
                var inBounds = isFeatureInBounds(feature);
                if (!inBounds) return; // 영역 밖의 건물은 상호작용 안함

                var rawAddr = feature.properties.주소; 
                var addr = normalizeAddress(rawAddr); // ★교정 완료: 클릭 시 팝업 띄울 때 주소 표준화 매칭
                var tenants = buildingGroup[addr] || [];

                // 층수 기준 오름차순 정렬
                tenants.sort(function(a, b) {
                    return parseInt(a.floor) - parseInt(b.floor);
                });

                // 팝업 내부 HTML 동적 렌더링
                var popupHtml = `<div class="custom-popup" style="width:260px;">`;
                popupHtml += `<div class="popup-building-title">건물 입점 현황</div>`;
                popupHtml += `<p style="font-size:11px; color:#718096; margin-top:-4px; margin-bottom:8px;">${addr}</p>`;

                if (tenants.length > 0) {
                    // 5개 정도 보이도록 max-height 설정 및 스크롤 추가
                    popupHtml += '<div style="max-height: 160px; overflow-y: auto; padding-right: 4px;">';
                    tenants.forEach(function(t) {
                        popupHtml += `
                            <div class="tenant-item">
                                <span class="floor-badge">${t.floor}F</span>
                                <b>${t.name}</b>
                                <span class="sector-badge">${t.sector}</span>
                            </div>`;
                    });
                    popupHtml += '</div>';
                } else {
                    popupHtml += `<p style="font-size:12px; color:#a0aec0; text-align:center;">입점 데이터가 없습니다.</p>`;
                }
                popupHtml += `</div>`;

                layer.bindPopup(popupHtml, { closeButton: true, autoPanPadding: [20, 20] });

                // 마우스 오버 시 하이라이트 효과
                layer.on({
                    mouseover: function(e) {
                        var l = e.target;
                        l.setStyle({ fillOpacity: 0.8, weight: 2.5 });
                    },
                    mouseout: function(e) {
                        var l = e.target;
                        var rawAddr = l.feature.properties.주소;
                        var addr = normalizeAddress(rawAddr);
                        var hasData = buildingGroup[addr] && buildingGroup[addr].length > 0;
                        l.setStyle({ 
                            fillOpacity: 0.6, 
                            weight: 1.5,
                            fillColor: hasData ? "#2B6CB0" : "#CBD5E0"
                        });
                    }
                });
            }
        }).addTo(map);

    